BEGIN; DO $$ BEGIN IF to_regprocedure('public.is_admin()') IS NULL THEN RAISE EXCEPTION 'Thieu ham kiem tra quyen is_admin(). Dung lai de kiem tra schema.'; END IF; IF to_regclass('public.customers') IS NULL THEN RAISE EXCEPTION 'Thieu bang customers. Dung lai de kiem tra schema.'; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='customers' AND column_name='deleted_at') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='customers' AND column_name='deleted_by') THEN RAISE EXCEPTION 'Bang customers thieu cot huy mem deleted_at/deleted_by.'; END IF; END $$; CREATE TABLE IF NOT EXISTS public.customer_deactivation_audit (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, customer_id uuid NOT NULL REFERENCES public.customers(id), customer_code text NOT NULL, customer_name text NOT NULL, customer_kind text NOT NULL CHECK (customer_kind IN ('parent','vendor')), deactivated_by uuid NOT NULL REFERENCES public.profiles(id), deactivated_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS idx_customer_deactivation_audit_customer_time ON public.customer_deactivation_audit(customer_id,deactivated_at DESC); ALTER TABLE public.customer_deactivation_audit ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "customer_deactivation_audit_select_admin" ON public.customer_deactivation_audit; CREATE POLICY "customer_deactivation_audit_select_admin" ON public.customer_deactivation_audit FOR SELECT TO authenticated USING (public.is_admin()); REVOKE ALL ON TABLE public.customer_deactivation_audit FROM PUBLIC,anon,authenticated; GRANT SELECT ON TABLE public.customer_deactivation_audit TO authenticated; CREATE OR REPLACE FUNCTION public.customers_block_hard_delete_v1() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Bi chan de giu lich su khach hang/Vendor: khong duoc xoa cung. Hay dung chuc nang Ngung.' USING ERRCODE='23503'; END $$; DROP TRIGGER IF EXISTS trg_customers_block_hard_delete_v1 ON public.customers; CREATE TRIGGER trg_customers_block_hard_delete_v1 BEFORE DELETE ON public.customers FOR EACH ROW EXECUTE FUNCTION public.customers_block_hard_delete_v1(); CREATE OR REPLACE FUNCTION public.admin_deactivate_customers_v1(p_customer_ids uuid[]) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_actor uuid:=auth.uid(); v_ids uuid[]; v_requested_count integer; v_locked_count integer; v_updated_count integer; v_now timestamptz:=now(); v_fk record; v_ref_count bigint; v_blockers text[]:=ARRAY[]::text[]; v_label text; v_sql text; BEGIN IF v_actor IS NULL OR NOT public.is_admin() THEN RAISE EXCEPTION 'Chi Admin hoac Super Admin dang hoat dong moi duoc ngung khach hang/Vendor.' USING ERRCODE='42501'; END IF; SELECT array_agg(x.id ORDER BY x.id),count(*) INTO v_ids,v_requested_count FROM (SELECT DISTINCT u.id FROM unnest(COALESCE(p_customer_ids,ARRAY[]::uuid[])) AS u(id) WHERE u.id IS NOT NULL) x; IF COALESCE(v_requested_count,0)=0 THEN RAISE EXCEPTION 'Chua chon khach hang/Vendor can ngung.'; END IF; IF v_requested_count>100 THEN RAISE EXCEPTION 'Moi lan chi duoc ngung toi da 100 khach hang/Vendor.'; END IF; IF cardinality(p_customer_ids)<>v_requested_count THEN RAISE EXCEPTION 'Danh sach khach hang/Vendor co dong rong hoac bi trung. Khong dong nao thay doi.'; END IF; PERFORM c.id FROM public.customers c WHERE c.id=ANY(v_ids) ORDER BY c.id FOR UPDATE; GET DIAGNOSTICS v_locked_count=ROW_COUNT; IF v_locked_count<>v_requested_count THEN RAISE EXCEPTION 'Co khach hang/Vendor khong ton tai. Khong dong nao thay doi.'; END IF; IF EXISTS (SELECT 1 FROM public.customers c WHERE c.id=ANY(v_ids) AND c.deleted_at IS NOT NULL) THEN RAISE EXCEPTION 'Co khach hang/Vendor da ngung truoc do. Khong dong nao thay doi.'; END IF; FOR v_fk IN SELECT n.nspname AS schema_name,cl.relname AS table_name,a.attname AS column_name,EXISTS(SELECT 1 FROM pg_attribute da WHERE da.attrelid=cl.oid AND da.attname='deleted_at' AND da.attnum>0 AND NOT da.attisdropped) AS has_deleted_at FROM pg_constraint co JOIN pg_class cl ON cl.oid=co.conrelid JOIN pg_namespace n ON n.oid=cl.relnamespace JOIN pg_attribute a ON a.attrelid=co.conrelid AND a.attnum=co.conkey[1] WHERE co.contype='f' AND co.confrelid='public.customers'::regclass AND array_length(co.conkey,1)=1 AND array_length(co.confkey,1)=1 AND co.conrelid<>'public.customer_deactivation_audit'::regclass ORDER BY n.nspname,cl.relname,a.attname LOOP v_sql:=format('SELECT count(*) FROM %I.%I r WHERE r.%I=ANY($1)',v_fk.schema_name,v_fk.table_name,v_fk.column_name); IF v_fk.has_deleted_at THEN v_sql:=v_sql||' AND r.deleted_at IS NULL'; END IF; IF v_fk.schema_name='public' AND v_fk.table_name='customers' THEN v_sql:=v_sql||' AND NOT (r.id=ANY($1))'; END IF; EXECUTE v_sql INTO v_ref_count USING v_ids; IF v_ref_count>0 THEN v_label:=CASE v_fk.table_name WHEN 'customers' THEN 'Vendor con' WHEN 'products' THEN 'Ma hang' WHEN 'delivery_plans' THEN 'Ke hoach giao hang' WHEN 'inventory_transactions' THEN 'Lich su kho' WHEN 'shipment_logs' THEN 'Lich su chuyen xe' WHEN 'inventory_opening_balances' THEN 'Ton dau ky' WHEN 'inventory_stocktake_lines' THEN 'Kiem ke' WHEN 'accounting_debt_invoices' THEN 'Cong no' WHEN 'accounting_debt_customer_terms' THEN 'Han cong no' WHEN 'returned_goods_records' THEN 'Hang tra ve' WHEN 'phoi_transactions' THEN 'Nhap phoi' ELSE v_fk.table_name END; v_blockers:=array_append(v_blockers,format('%s: %s dong',v_label,v_ref_count)); END IF; END LOOP; IF cardinality(v_blockers)>0 THEN RAISE EXCEPTION 'Khong the ngung vi khach hang/Vendor dang duoc su dung trong: %. Lich su va so lieu khong thay doi.',array_to_string(v_blockers,'; ') USING ERRCODE='23503'; END IF; INSERT INTO public.customer_deactivation_audit(customer_id,customer_code,customer_name,customer_kind,deactivated_by,deactivated_at) SELECT c.id,c.code,c.name,CASE WHEN c.parent_customer_id IS NULL THEN 'parent' ELSE 'vendor' END,v_actor,v_now FROM public.customers c WHERE c.id=ANY(v_ids) ORDER BY c.id; UPDATE public.customers SET deleted_at=v_now,deleted_by=v_actor WHERE id=ANY(v_ids) AND deleted_at IS NULL; GET DIAGNOSTICS v_updated_count=ROW_COUNT; IF v_updated_count<>v_requested_count THEN RAISE EXCEPTION 'Khong ngung du so dong da chon. Toan bo thao tac duoc hoan tac.'; END IF; RETURN jsonb_build_object('success',true,'deactivated_count',v_updated_count,'message','Da ngung khach hang/Vendor. Lich su khong bi xoa.'); END $$; REVOKE ALL ON FUNCTION public.admin_deactivate_customers_v1(uuid[]) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.admin_deactivate_customers_v1(uuid[]) TO authenticated; NOTIFY pgrst,'reload schema'; COMMIT;
